// Real-estate glossary. Every term: simple explanation, professional explanation, worked example, FAQ.
// Facts only: legal/tax references are general and readers are told to verify current figures.
const U = '2026-09-16'
const HE = { simple: 'בקצרה', pro: 'ההסבר המקצועי', example: 'דוגמה מהשטח', why: 'למה זה חשוב בעסקה' }
const EN = { simple: 'In short', pro: 'The professional explanation', example: 'Example from the field', why: 'Why it matters in a deal' }

function term(slug, cta, related, he, en) {
  const build = (t, L) => ({
    h1: t.h1, cardTitle: t.h1, metaTitle: t.metaTitle, description: t.description, summaryText: t.description, summary: t.summary || t.description,
    sections: [
      { h2: L.simple, paras: [t.simple] },
      { h2: L.pro, paras: t.pro },
      { h2: L.example, paras: [t.example] },
      ...(t.why ? [{ h2: L.why, bullets: t.why }] : []),
    ],
    faq: t.faq,
  })
  return { slug, cta, updated: U, related, he: build(he, HE), en: build(en, EN) }
}

